`timescale 1ns / 1ps
// Bit-exact controller test. Vectors are generated by model/anc/gen_vectors.py.
// Run from repository root so sim/vectors paths resolve.

module tb_fxlms;
    localparam integer L = 64;
    localparam integer M = 128;
    localparam integer NUM = 4096;
    localparam integer WAIT_CYCLES = 420; // controller worst-case is < 400 clocks

    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg rst = 1'b1;
    reg sample_tick = 1'b0;
    reg anc_en = 1'b1;
    reg w_reset = 1'b0;
    reg signed [23:0] x_ref = 24'sd0;
    reg signed [23:0] e_err = 24'sd0;
    wire signed [23:0] y_anti;
    wire [6:0] shat_addr;
    reg signed [23:0] shat_data = 24'sd0;
    wire w_over;

    reg signed [23:0] x_mem [0:NUM-1];
    reg signed [23:0] e_mem [0:NUM-1];
    reg signed [23:0] y_expected [0:NUM-1];
    reg w_expected [0:NUM-1];
    reg signed [23:0] shat_mem [0:M-1];

    // One-cycle synchronous read, matching C's proposed shat RAM.
    always @(posedge clk)
        shat_data <= shat_mem[shat_addr];

    fxlms #(.L(L), .M(M), .MU_SHIFT(7)) dut (
        .clk(clk),
        .rst(rst),
        .sample_tick(sample_tick),
        .anc_en(anc_en),
        .w_reset(w_reset),
        .x_ref(x_ref),
        .e_err(e_err),
        .y_anti(y_anti),
        .shat_addr(shat_addr),
        .shat_data(shat_data),
        .w_over(w_over)
    );

    integer i;
    integer errors;

    initial begin
        errors = 0;
        $readmemh("sim/vectors/fxlms_xref.hex", x_mem);
        $readmemh("sim/vectors/fxlms_eerr.hex", e_mem);
        $readmemh("sim/vectors/fxlms_yanti.hex", y_expected);
        $readmemh("sim/vectors/fxlms_w_over.hex", w_expected);
        $readmemh("sim/vectors/fxlms_shat.hex", shat_mem);

        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);

        for (i = 0; i < NUM; i = i + 1) begin
            // Inputs are stable before the active clock edge.
            x_ref = x_mem[i];
            e_err = e_mem[i];
            sample_tick = 1'b1;
            @(negedge clk);
            sample_tick = 1'b0;

            repeat (WAIT_CYCLES) @(negedge clk);

            if (y_anti !== y_expected[i]) begin
                $display("MISMATCH sample=%0d y_got=%0d (0x%h) y_exp=%0d (0x%h)",
                         i, y_anti, y_anti, y_expected[i], y_expected[i]);
                errors = errors + 1;
                if (errors >= 10) $fatal(1, "Too many y_anti mismatches");
            end
            if (w_over !== w_expected[i]) begin
                $display("MISMATCH sample=%0d w_over_got=%b w_over_exp=%b",
                         i, w_over, w_expected[i]);
                errors = errors + 1;
                if (errors >= 10) $fatal(1, "Too many w_over mismatches");
            end
        end

        if (errors == 0)
            $display("PASS: all %0d FxLMS samples match the fixed-point Python model bit-for-bit", NUM);
        else
            $fatal(1, "FAIL: %0d mismatches", errors);
        $finish;
    end
endmodule
